import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import './googlemap.css';

const Map = () => {
    const location = useLocation();
    const petLocation = location.state?.location;

    useEffect(() => {
        const script = document.createElement('script');
        script.src = `https://maps.googleapis.com/maps/api/js?key=AIzaSyAyCujJ188OdhtBjKLmV2CheQgDnqEa-9o&callback=initMap`;
        script.async = true;
        script.defer = true;
        script.onload = () => {
            initMap();
        };
        document.head.appendChild(script);

        return () => {
            document.head.removeChild(script);
        };
    }, [petLocation]);

    const initMap = () => {
        const defaultLocation = { lat: 32.9533, lng: 35.2176 };
        const mapLocation = petLocation ? { lat: petLocation.lat, lng: petLocation.lng } : defaultLocation;

        const map = new window.google.maps.Map(document.getElementById('map'), {
            zoom: 12,
            center: mapLocation
        });

        if (petLocation) {
            new window.google.maps.Marker({
                position: mapLocation,
                map: map,
                title: 'Pet Location'
            });
        }
    };

    return (
        <div className="container">
            <div id="map" style={{ height: '400px', width: '100%' }}></div>
        </div>
    );
};

export default Map;
